205	    /**
206	     * Retrieves all inputs in the correct form using helper methods
207	     * defined in this class and launches the simulation.
208	     *
209	     * @param habitatChoiceDisplay (JComboBox<String>) The ComboBox used by the user to select a habitat.
210	     * @param climateChangeScenarioChoiceDisplay (JComboBox<String>) The ComboBox used by the user to select a climate change scenario.
211	     */
212	    private void getInputsAndLaunchSimulation(
213	        JComboBox<String> habitatChoiceDisplay,
214	        JComboBox<String> climateChangeScenarioChoiceDisplay
215	    )
216	    {
217	        String chosenHabitat = getHabitatInput(habitatChoiceDisplay);
218	        if (chosenHabitat != null)
219	        {
220	            List<Integer> numbersInputted = getNumericValuesOfUserInputs();
221	            if (numbersInputted != null) {
222	                Map<String, Integer> selectedAnimals = generateAnimalDictionary(numbersInputted);
223	                if (selectedAnimals != null) {
224	                    String chosenSimulation = getScenarioInput(climateChangeScenarioChoiceDisplay);
225	                    if (chosenSimulation != null) {
226	                        launchSimulation(chosenHabitat, selectedAnimals, chosenSimulation);
227	                    }
228	                }
229	            }
230	        }
231	    }
