233	    /**
234	     * Return a list of Integers from the Strings inputted by the user in the various TextFields.
235	     * Source for try/catch construct to catch non-numerical values: https://stackabuse.com/java-check-if-string-is-a-number/
236	     *
237	     * @return (List<Integer>) The list of integers inputted by the user.
238	     */
239	    private List<Integer> getNumericValuesOfUserInputs()
240	    {
241	        List<Integer> inputtedNumbers = new ArrayList<>();
242	        for (JTextField inputReceiver : animalNumberReceivers)
243	        {
244	            String inputValue = inputReceiver.getText();
245	            try {
246	                int numericValue = Integer.parseInt(inputValue);
247	                inputtedNumbers.add(numericValue);
248	            } catch (NumberFormatException e) {
249	                throwErrorMessage("One of the values inputted is not a number or one cell was left blank, please try again.");
250	                return null;
251	            }
252	        }
253	        return inputtedNumbers;
254	    }
