265	    /**
266	     * Generates a HashMap associating the name of each animal with the number
267	     * of this animal that must be created. This method heavily relies on the fact
268	     * that animal names are stored in the animalList in the same order that they were on screen.
269	     *
270	     * @param numberOfEachAnimals (List<Integer>) The list of animal counts aligned with the displayed animal list.
271	     */
272	    private Map<String, Integer> generateAnimalDictionary(List<Integer> numberOfEachAnimals)
273	    {
274	        if (numberOfEachAnimals.size() != animalList.size()) {
275	            return null;
276	        }
277	
278	        HashMap<String, Integer> selectedAnimals = new HashMap<>();
279	        for (int i=0; i<numberOfEachAnimals.size(); i++) {
280	            selectedAnimals.put(animalList.get(i), numberOfEachAnimals.get(i));
281	        }
282	        return selectedAnimals;
283	    }
